code.sql:
-- PostGIS only stores the raw tables here;
-- the spatial join runs in the browser.
SELECT id, grp, geom FROM points;

code.js:
// every stage runs here: fetch the raw tables once
fetch("boston_social_infra.geojson")
  .then(r => r.json())
  .then(drawMap);

code.sql:
CREATE MATERIALIZED VIEW joined_view AS
SELECT p.id, p.grp, c.cell, c.neighborhood
FROM points p
JOIN cells c ON ST_Within(p.geom, c.geom);

-- refresh nightly, not on every click
REFRESH MATERIALIZED VIEW joined_view;

code.js:
// the joined rows arrive once; filter and count run here
fetch("/sites")
  .then(r => r.json())
  .then(drawMap);

// a new request on every neighbourhood change
fetch("/sites?hood=" + encodeURIComponent("Roxbury"))
  .then(r => r.json())
  .then(drawMap);

